const item = $input.first();
const headers = (item.json && item.json.headers) || {};
function pick(name) {
  const want = String(name).toLowerCase();
  for (const [k, v] of Object.entries(headers)) {
    if (String(k).toLowerCase() === want) {
      return String(Array.isArray(v) ? v[0] : v ?? '');
    }
  }
  return '';
}
const given = pick('x-n8n-notification-secret') || pick('authorization').replace(/^Bearer\s+/i, '').trim();
const expected = String(($vars && $vars.TELEGRAM_NOTIFICATION_SECRET) || ($env && $env.N8N_TELEGRAM_NOTIFICATION_WEBHOOK_SECRET) || '').trim();
if (expected) {
  if (given !== expected) throw new Error('Bildirim yetkisiz');
} else if (!given) {
  throw new Error('X-N8N-Notification-Secret header gerekli');
}
const body = (item.json && item.json.body) || {};
const mesaj = typeof body.mesaj === 'string' && body.mesaj.trim() ? body.mesaj.trim() : 'Locus test bildirimi';
return [{ json: { ok: true, mesaj } }];
